#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct chunk {
    size_t size;
    struct chunk *prev;
    struct chunk *next;
} chunk_t;

/* Unsafe unlink – assumes prev->next == this && next->prev == this */
void unsafe_unlink(chunk_t *prev, chunk_t *this, chunk_t *next) {
    /* Directly rewires pointers without checking for cycles or double‑free */
    this->prev = prev->prev;   // BUG: may become NULL if prev is NULL
    this->next = next->next;   // BUG: may become NULL if next is NULL
}

int main(void) {
    /* Allocate two adjacent chunks */
    chunk_t c1 = { .size = 64, .prev = NULL, .next = NULL };
    chunk_t c2 = { .size = 64, .prev = &c1, .next = NULL };

    /* Link them together */
    c1.next = &c2;
    c2.prev = &c1;

    /* Simulate a free operation that calls unsafe_unlink */
    unsafe_unlink(&c1, &c2, &c2); // BUG: this points to c2 (the node being freed)

    /* Corrupted list – now any subsequent allocation can be tricked into linking to an attacker‑controlled address */
    return 0;
