#include <limits.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_ALLOWED ((size_t)1 << 30)   /* example limit */

int safe_alloc(uint32_t user_len)
{
    /* Detect overflow before promotion */
