/*
 * Demonstrates a Race Condition during signal handling.
 * The SIGINT handler calls `printf`, which is not async-signal-safe.
 * The program installs the handler with SA_RESTART so that system calls
 * are automatically restarted after the signal.
 */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

/* Global flag to indicate whether we are inside the handler */
static volatile sig_atomic_t in_handler = 0;

/* Safe wrapper – only safe functions */
static void safe_print(const char *msg)
{
    /* Use write() which is async-signal-safe */
    write(STDOUT_FILENO, msg, strlen(msg));
}

/* Unsafe wrapper – printf() is not async-signal-safe */
static void unsafe_print(const char *msg)
{
    printf("%s\n", msg);   // May call malloc/free internally → race
}

static void sigint_handler(int signo)
{
    /* Mark that we entered the handler */
    in_handler = 1;
    /* Attempt to print – this can deadlock or corrupt internal state */
    unsafe_print("Signal received");
    /* If we reach here without crashing, reset flag */
    in_handler = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;   // Allows system calls to be restarted automatically

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    while (!in_handler) {
        /* Busy loop – keep CPU busy so we can send SIGINT quickly */
        for (volatile int i = 0; i < 1000000; ++i);
        usleep(10); // tiny pause to avoid hogging CPU too much
    }

    printf("Exiting after SIGINT\n");
    return EXIT_SUCCESS;
}
```
### Why this is unsafe (race condition)
1. **Async‑signal safety** – POSIX defines only a small set of functions that may be safely called from a signal handler (e.g., `write`, `_exit`, `sigatomic_*` operations). `printf` may allocate memory or acquire locks internally; if it runs concurrently with another instance of itself (e.g., from another thread), undefined behavior occurs.
2. **Race window** – The flag `in_handler` is written without any synchronization primitive other than the implicit atomicity of plain stores on most platforms. If another thread reads this flag while the handler is still executing, it may see an intermediate state (`in_handler == 1`) and incorrectly assume that no further signals have arrived.
3. **Potential deadlock** – If `printf` internally tries to acquire a mutex held by another thread that also receives SIGINT, both threads could block forever because each holds the lock needed by the other.
4. **Signal masking** – The default action for many signals (including SIGINT) blocks further delivery until the current instance returns unless explicitly unblocked with `sigprocmask`. By installing our own handler without restoring the original mask (`SA_RESTART` does not affect signal masking), we can unintentionally prevent subsequent signals from being delivered.
5. **Mitigation** – Use only async‑signal‑safe functions inside handlers (e.g., `write`, `_exit`, or set flags via `volatile sigatomic_*` variables). Install handlers with appropriate flags (`SA_RESTART`) to avoid blocking other signals.

