#include <sys/random.h>
#include <stdint.h>

int generate_session_key(unsigned char *key, size_t len) {
    if (!key || len == 0) return -1;               // basic validation
    /* Ensure we have enough entropy – getrandom() will fail if not */
    ssize_t ret = getrandom(key, len, 0);
    if (ret != 0) {
