    uint8_t lenbuf[8];
    memcpy(lenbuf + sizeof(lenbuf) - sizeof(__uint64), &data->length * 8,
           sizeof(__uint64));

    memcpy(&outer[sizeof(__uint32)], lenbuf + sizeof(__uint64) - sizeof(__uint32),
           sizeof(__uint32));

