    unsigned short addr = 0x50;       /* example EEPROM address */
    unsigned char buf[64];           /* enough for typical EEPROM sizes */
    ssize_t nbytes;
    int fd;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <I2C-bus-number>\n", argv[0]);
        return EXIT_FAILURE;
    }

    fd = open(dev, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

